% Independent bounded-source sine controls; actual MATLAB sine output.
R='/scratch/gpfs/GILLES/mg6942/chebfun_matlab_ref';
[status,rev]=system(sprintf('git -C "%s" rev-parse HEAD',R));
assert(status==0 && startsWith(strtrim(rev),'7574c77'));
D=fileparts(mfilename('fullpath'));
target=fullfile(D,'native_extra.mat');assert(~isfile(target));
knots=[pi/4 pi/2 3*pi/4 pi];
neighbors=reshape(knots'+(-2:2).*eps(knots'),[],1);
angles=unique([linspace(-pi,pi,4097)';neighbors;-neighbors;0;-0;realmin;-realmin]);
angles=angles(abs(angles)<=pi);
sines=sin(angles);cosines=cos(angles);
save(target,'angles','sines','cosines','rev','-v7');
